from importlib.machinery import SourceFileLoader
from pathlib import Path
p=Path(__file__).parent;m=SourceFileLoader('tle',str(p/'author-helper.py')).load_module()
m.lesson(37,'Pagpili ng chassis tools ayon sa papel','Ihiwalay ang tools sa marking, hole location, cutting, at threading at ipaliwanag ang layout check bago magproseso.',[
('Itakda ang posisyon bago humubog','Chassis ang base na kinakabitan ng mga bahagi ng kagamitan. Magkaiba ang scriber na nagmamarka ng sukat/posisyon sa metal at punch na gumagawa ng uka sa center ng butas. Kung maaaring baguhin ang layout, huwag agad mag-ukit ng permanenteng linya; gumawa ng temporary mark ayon sa procedure at itugma. Itapat ang reference face at orientation at tiyaking kasya ang piyesa bago magpatuloy.'),
('Pagputol, paggawa ng butas, at thread','Drill ang para sa butas at tap pilot hole; hole saw sa mas malaking butas para sa equipment. Tap ang para sa female thread at die para sa male thread. Sa milling machine ginagamit ang end mill na may cutting edges sa paligid at dulo. Kahit parehong “cutting,” hindi pareho ang materyal, hugis, makina, at kailangang sukat.'),
('Hindi tapos sa pagputol','Kung hacksaw ang putol at file ang hand finish, suriin ang burr at interference sa piyesa bukod sa cut face. Burr ang protrusion mula sa cutting/drilling ng metal at maaaring magdulot ng sugat o assembly defect. Ihanda ang tool, fixing, at chip collection bago magtrabaho at iwasan ang hindi nilalayong paggamit.')],['Pagmamarka ng processing dimensions o hole position sa workpiece.','Tool na gumagawa ng uka sa center ng butas at katulad nito.','Tool na gumagawa ng female thread.','Tool na gumagawa ng male thread.'],'Gabay na 30 minuto: 10 teksto, 7 tools, 8 sequence, 5 paliwanag.\nPagsulat: Iuri ayon sa gamit ang scriber, punch, drill, tap, die, at file. Isulat ang order ng pag-check laban sa maling butas ng control panel. Magpaliwanag ng dalawang epekto ng burr sa susunod na assembly.\nSariling pagsusuri: Hindi ba napagpapalit ang tool para sa female/male thread at nauuna ang location check sa cutting?',['I-fix nang maayos ang workpiece at mag-ingat sa matalim na scriber, cut face, at chips.','Sundin ang safety procedure sa rotating tools; huwag alisin ang chips gamit ang kamay o tool habang umiikot.'],'Piliin ang tool ayon sa bagay at layunin. Ituring na magkakaugnay ang pagtiyak ng posisyon, machining, at burr check.')
m.lesson(38,'Pagtutugma ng reference sa comparison at height measurement','Ihiwalay ang papel ng dial gauge, height gauge, scale, at surface plate at ipaliwanag ang reference at pagbasa.',[
('Pagkuha ng pagbabago sa dial gauge','Pinalalaki nang mekanikal ng dial gauge ang maliit na galaw ng probe at ipinapakita sa pointer. Ginagamit sa runout, flatness, at paghahambing ng sukat. Tiyakin sa modelo ang bawat division at buong ikot; huwag absolute dimension mula sa galaw lamang. Matapos i-set ang reference, ihambing sa parehong contact condition at itala ang direksiyon at dami ng galaw.'),
('Ihiwalay ang taas at lalim','Height gauge ang sumusukat mula reference plane o nagmamarka sa kinakailangang taas. Kahit may caliper-like reading, hindi lahat ng gamit ay pareho. Huwag ituring na laging pang-hole depth; piliin ayon sa dimensiyon. Binabago ng dumi sa reference o base ang posisyon ng pagsukat, kaya tingnan bago gamitin.'),
('Kahulugan ng surface plate at end face','Surface plate ang nagbibigay ng reference plane sa pagsukat at assembly, hindi mismong instrumentong nagpapakita ng dimensiyon. May metal scale na end face ang simula. Huwag ipaghalo ang end reference at caliper reference line; tingnan ang wear, dumi, pagdikit, at kailangang accuracy.')],['Pagsukat ng pagbabago o diperensiya ng dimensiyon sa reference.','Bahaging dumidikit sa workpiece at naghahatid ng displacement.','Gamit sa taas mula reference plane o marking.','Mesang nagsisilbing reference plane sa measurement at assembly.'],'Gabay na 30 minuto: 10 teksto, 7 pagpili ng instrumento, 8 reference/pagbasa, 5 paglalagom.\nPagsulat: Pumili nang may dahilan para sa shaft runout, taas mula plane, hole depth, at magaspang na length check. Sa palagay na0.01 mmang division, kalkulahin ang diperensiya ng4division mula reference. Ipaliwanag ang epekto ng dumi sa surface plate.\nSariling pagsusuri: Hindi ba ginagarantiyang pareho ang least division at aktuwal na accuracy?',['Huwag ihulog ang instrumento o piliting itulak ang probe.','Sukatin ang rotating objects sa aprubadong ligtas na paraan at huwag basta paandarin ang makina.'],'Iba ang reference sa comparison, height, at length. Tiyakin ang plate, end face, at reference at sukatin ayon sa gamit ng instrumento.')
m.lesson(39,'Pagtiyak sa dami at kondisyon ng electrical meters','Iuri ang LCR meter, thermocouple, lux meter, at gaussmeter ayon sa dami at ipaliwanag ang measurement conditions.',[
('LCR meter para sa component values','Sinusukat ng LCR meter ang inductance L ng coil, capacitance C, resistance R, impedance, at iba pa. Iba ang target/paraan kaysa tester ng resistance at voltage. Itugma sa specification ang uri ng piyesa, connection, at test frequency; huwag numero lamang ang hatol. Tiyakin din sa device/procedure kung maaaring sukatin habang konektado sa circuit.'),
('Thermocouple gamit ang temperature difference','Ginagamit ng thermocouple ang thermoelectric voltage mula sa magkaibang metal at temperature difference ng junctions. Bukod sa sinusukat na temperature, mahalaga ang reference junction. Itugma ang type, compensation wire, polarity, at meter setting. Huwag gawing pangkalahatan ang temperature range mula type lamang; sundin ang product specification at paggamit.'),
('Magkaibang dami ang liwanag at magnetic field','Sinusukat ng lux meter ang illuminance sa light sensor; gaussmeter ang magnetic flux density gamit ang Hall element at iba pa. Magkaiba ang maliwanag at malakas na magnetic field. Nakaaapekto ang orientation, posisyon, at external influences; itugma ang conditions sa paghahambing. Irekord pati unit at instrument name upang maiwasan ang pagkalito.')],['Daming nagpapahayag ng katangian ng coil at iba pa sa pagbabago ng current.','Temperature sensor gamit ang magkaibang metal at thermoelectric voltage ng temperature difference.','Daming nagpapahayag ng antas ng liwanag na dumarating sa ibabaw.','Isa sa mga daming nagpapahayag ng magnetic-field state.'],'Gabay na 30 minuto: 10 teksto, 7 dami at meter, 8 conditions, 5 paliwanag.\nPagsulat: Itugma ang L, C, R, temperature, illuminance, at magnetic flux density sa meter. Magbigay ng tatlong kundisyon sa thermocouple replacement. Ipaliwanag kung bakit hindi agad maihahambing ang parehong produktong sinukat mula ibang posisyon.\nSariling pagsusuri: Nasusuri ba ang sensor at conditions at hindi ginagawang range ng lahat ang isang temperatura?',['Sundin ang meter specs at aprubadong isolation/discharge sa live measurement at residual charge ng capacitor.','Huwag hawakan ang mainit na bahagi at sundin ang heat limits ng sensor at compensation wire.'],'Pumili ayon sa sinusukat at itala ang unit, connection, at sensor conditions. Tingnan sa product specification ang thermocouple range.')
m.lesson(40,'Pagsunod sa paghahanda ng drilling at tapping','Ihiwalay ang reference location, pilot hole, threading, at deburring at ipaliwanag ang pasyang huwag pilitin ang tool.',[
('Itugma ang center bago magproseso','Sukatin ang mounting hole mula sa takdang reference face. Gumawa ng temporary center/outline, ilagay ang tunay na device upang tingnan ang interference at orientation, saka gumamit ng punch ayon sa procedure. Mahirap ibalik ang maling butas. Kung kailangan, unti-unti mula pilot hole ang malaking butas at siguraduhing naka-fix ang workpiece.'),
('Ihiwalay ang pilot hole at female thread','Tapping ang paggawa ng female thread sa loob ng pilot hole. Hindi nominal thread diameter ang pilot diameter; tingnan ang table para sa thread diameter, pitch, materyal, at proseso. Sundin ang center drilling, pilot drilling, chamfering, at cutting-oil applicability. Huwag iisang pilot size para sa lahat mula sa rough ratio lamang.'),
('Perpendicularity at chip removal','Sa hand tapping, hawakan gamit ang tap handle at panatilihin ang angkop na orientation sa workpiece. Alisin ang chips sa pagkakasunod at paraang angkop sa tool; huwag pilitin kapag biglang bumigat. Upang maiwasan ang broken tap at thread defect, tingnan ang hole, tool, lubrication, at chips. Pagkatapos, tingnan ang burr at thread at huwag mag-iwan ng chips sa loob ng kagamitan.')],['Butas na inuuna para sa kasunod na machining.','Thread sa loob ng butas.','Pagproseso ng corner o hole edge sa takdang hugis.','Tool sa paghawak at pag-ikot ng tap sa kamay.'],'Gabay na 30 minuto: 10 teksto, 8 sequence cards, 7 depekto, 5 paglalagom.\nPagsulat: Hatiin sa anim na yugto mula location check hanggang burr check. Magbigay ng tatlong kondisyon sa pilot size. Gumawa ng stop/check report kapag bumigat ang tap sa kamay.\nSariling pagsusuri: Hindi ba pinagkakamali ang nominal thread at pilot diameter at naiiwasan ang sobrang puwersa?',['Huwag basta ikabit ang hand tap sa umiikot na drill chuck; sundin ang aprubadong paggamit ng makina at tool.','Huwag hawakan lamang sa kamay ang workpiece habang pinuputol; alisin nang ligtas ang chips pagkatapos huminto.'],'Tiyakin ang location at pilot conditions bago machining. Kapag mabigat ang tap, huwag pilitin; alamin ang sanhi.')
